-- Generated by `make contracts` from contracts/ (conformedDimensions) and contracts/models/dim_place.odcs.yaml. Do not edit: change the contract and regenerate.
-- The gazetteer: declared places (contracts/models/dim_place.odcs.yaml), the Census state and county
-- code files, and the partial areas the facts use. GBD location names are geo.py's (states, DC, PR).
with declared as (
    select * from (values
        ('USA', 'United States', 'nation', NULL, false, NULL, NULL, NULL, 'USA', '840', 'United States', NULL, 'UN M49 (https://unstats.un.org/unsd/methodology/m49/overview/, read 2026-11-25): United States of America, M49 840, ISO-alpha3 USA. GBD location name as geo.py gives it (the name the IHME GBD connector accepts).'),
        ('US-26163', 'Wayne County', 'county', 'US-26', false, NULL, NULL, NULL, NULL, NULL, NULL, 'US-26163/detroit, US-26163/out-wayne', 'Census county code file (26 163 Wayne County); never_add_with from the maintainer''s geography rule (tools.GEOGRAPHY_TRAPS): Out-Wayne County reports exclude the City of Detroit, which has its own health department.'),
        ('US-26163/detroit', 'City of Detroit', 'city', 'US-26163', true, 'The City of Detroit only, reported by the Detroit Health Department; part of Wayne County.', NULL, NULL, NULL, NULL, NULL, 'US-26163, US-26163/out-wayne', 'Maintainer''s geography rule (tools.GEOGRAPHY_TRAPS): the City of Detroit has its own health department.'),
        ('US-26163/out-wayne', 'Out-Wayne County', 'partial_area', 'US-26163', true, 'Wayne County excluding the City of Detroit, as MDHHS and Wayne County report it.', NULL, NULL, NULL, NULL, NULL, 'US-26163, US-26163/detroit', 'Maintainer''s geography rule (tools.GEOGRAPHY_TRAPS): Out-Wayne County reports exclude the City of Detroit.')
    ) as t(place_key, place_name, place_level, parent_key, is_partial_area, place_note, fips, postal, iso3, m49, gbd_location_name, never_add_with, key_source)
),

gbd_names as (
    select * from (values
        ('01', 'Alabama'),
        ('02', 'Alaska'),
        ('04', 'Arizona'),
        ('05', 'Arkansas'),
        ('06', 'California'),
        ('08', 'Colorado'),
        ('09', 'Connecticut'),
        ('10', 'Delaware'),
        ('11', 'District of Columbia'),
        ('12', 'Florida'),
        ('13', 'Georgia'),
        ('15', 'Hawaii'),
        ('16', 'Idaho'),
        ('17', 'Illinois'),
        ('18', 'Indiana'),
        ('19', 'Iowa'),
        ('20', 'Kansas'),
        ('21', 'Kentucky'),
        ('22', 'Louisiana'),
        ('23', 'Maine'),
        ('24', 'Maryland'),
        ('25', 'Massachusetts'),
        ('26', 'Michigan'),
        ('27', 'Minnesota'),
        ('28', 'Mississippi'),
        ('29', 'Missouri'),
        ('30', 'Montana'),
        ('31', 'Nebraska'),
        ('32', 'Nevada'),
        ('33', 'New Hampshire'),
        ('34', 'New Jersey'),
        ('35', 'New Mexico'),
        ('36', 'New York'),
        ('37', 'North Carolina'),
        ('38', 'North Dakota'),
        ('39', 'Ohio'),
        ('40', 'Oklahoma'),
        ('41', 'Oregon'),
        ('42', 'Pennsylvania'),
        ('44', 'Rhode Island'),
        ('45', 'South Carolina'),
        ('46', 'South Dakota'),
        ('47', 'Tennessee'),
        ('48', 'Texas'),
        ('49', 'Utah'),
        ('50', 'Vermont'),
        ('51', 'Virginia'),
        ('53', 'Washington'),
        ('54', 'West Virginia'),
        ('55', 'Wisconsin'),
        ('56', 'Wyoming'),
        ('72', 'Puerto Rico')
    ) as t(state_fips, gbd_location_name)
),

states as (
    select 'US-' || s.state_fips as place_key, s.state_name as place_name, 'state' as place_level,
        'USA' as parent_key, false as is_partial_area, cast(null as varchar) as place_note,
        s.state_fips as fips, s.postal, cast(null as varchar) as iso3, cast(null as varchar) as m49,
        g.gbd_location_name, cast(null as varchar) as never_add_with,
        'census_fips_state' as key_source
    from {{ ref('stg_census_fips_state') }} as s
    left join gbd_names as g on g.state_fips = s.state_fips
),

counties as (
    select 'US-' || c.state_fips || c.county_fips as place_key, c.county_name as place_name,
        'county' as place_level, 'US-' || c.state_fips as parent_key, false as is_partial_area,
        cast(null as varchar) as place_note, c.state_fips || c.county_fips as fips, c.postal,
        cast(null as varchar) as iso3, cast(null as varchar) as m49,
        cast(null as varchar) as gbd_location_name,
        d.never_add_with,
        'census_fips_county' as key_source
    from {{ ref('stg_census_fips_county') }} as c
    left join declared as d on d.place_key = 'US-' || c.state_fips || c.county_fips
),

partial_areas as (
    select place_key, min(place_label) as place_name, 'partial_area' as place_level,
        min(place_parent_key) as parent_key, true as is_partial_area, min(place_note) as place_note,
        cast(null as varchar) as fips, cast(null as varchar) as postal, cast(null as varchar) as iso3,
        cast(null as varchar) as m49, cast(null as varchar) as gbd_location_name,
        cast(null as varchar) as never_add_with, 'cdc_haicviz_cdi' as key_source
    from {{ ref('int_cdc_haicviz_cdi') }}
    where place_status = 'partial_area'
    group by place_key
    union all
    select place_key, min(place_label) as place_name, 'partial_area' as place_level,
        min(place_parent_key) as parent_key, true as is_partial_area, min(place_note) as place_note,
        cast(null as varchar) as fips, cast(null as varchar) as postal, cast(null as varchar) as iso3,
        cast(null as varchar) as m49, cast(null as varchar) as gbd_location_name,
        cast(null as varchar) as never_add_with, 'cdc_nhsn_ar_hai' as key_source
    from {{ ref('int_cdc_nhsn_ar_hai') }}
    where place_status = 'partial_area'
    group by place_key
    union all
    select place_key, min(place_label) as place_name, 'partial_area' as place_level,
        min(place_parent_key) as parent_key, true as is_partial_area, min(place_note) as place_note,
        cast(null as varchar) as fips, cast(null as varchar) as postal, cast(null as varchar) as iso3,
        cast(null as varchar) as m49, cast(null as varchar) as gbd_location_name,
        cast(null as varchar) as never_add_with, 'cdc_nndss_weekly' as key_source
    from {{ ref('int_cdc_nndss_weekly') }}
    where place_status = 'partial_area'
    group by place_key
    union all
    select place_key, min(place_label) as place_name, 'partial_area' as place_level,
        min(place_parent_key) as parent_key, true as is_partial_area, min(place_note) as place_note,
        cast(null as varchar) as fips, cast(null as varchar) as postal, cast(null as varchar) as iso3,
        cast(null as varchar) as m49, cast(null as varchar) as gbd_location_name,
        cast(null as varchar) as never_add_with, 'cdc_respnet' as key_source
    from {{ ref('int_cdc_respnet') }}
    where place_status = 'partial_area'
    group by place_key
    union all
    select place_key, min(place_label) as place_name, 'partial_area' as place_level,
        min(place_parent_key) as parent_key, true as is_partial_area, min(place_note) as place_note,
        cast(null as varchar) as fips, cast(null as varchar) as postal, cast(null as varchar) as iso3,
        cast(null as varchar) as m49, cast(null as varchar) as gbd_location_name,
        cast(null as varchar) as never_add_with, 'census_county_pop' as key_source
    from {{ ref('int_census_county_pop') }}
    where place_status = 'partial_area'
    group by place_key
)

select place_key, place_name, place_level, parent_key, is_partial_area, place_note, fips, postal, iso3, m49, gbd_location_name, never_add_with, key_source from declared
where place_key not in (select place_key from counties)
union all
select place_key, place_name, place_level, parent_key, is_partial_area, place_note, fips, postal, iso3, m49, gbd_location_name, never_add_with, key_source from states
union all
select place_key, place_name, place_level, parent_key, is_partial_area, place_note, fips, postal, iso3, m49, gbd_location_name, never_add_with, key_source from counties
union all
select place_key, place_name, place_level, parent_key, is_partial_area, place_note, fips, postal, iso3, m49, gbd_location_name, never_add_with, key_source from partial_areas
where place_key not in (select place_key from declared)
